mapper.update:

/*commonMdCmBuyPriceApproval.updateBuyPriceReqHdStatus*/
UPDATE KEPMGPHD
   SET STATUS          = #{STATUS}
     , CONFIRM_DATE    = SYSDATE
     , CONFIRM_USER_ID = #{USER_ID}
     , CHANGE_DATE     = SYSDATE
 WHERE BUYER = #{KEY_2}
   AND PM_NO = #{KEY_1}
   AND STATUS = 'C'


/*commonMdCmBuyPriceApproval.updateBuyPriceReqDtStatus*/
UPDATE KEPMGPDT
   SET STATUS          = #{STATUS}
     , CONFIRM_DATE    = SYSDATE
     , CONFIRM_USER_ID = #{USER_ID}
     , CHANGE_DATE     = SYSDATE
 WHERE BUYER = #{KEY_2}
   AND PM_NO = #{KEY_1}

mapper.select:

/*commonMdCmBuyPriceApproval.selectBuyPriceReqDtList*/
SELECT
  D.CMS_CATLG_ID
 ,TRIM(TO_CHAR(D.CATLG_SEQ))     AS CATLG_SEQ
 ,TRIM(TO_CHAR(D.CH_LIST_PRICE)) AS CH_BUY_PRICE
 ,D.BELOW_TEXT                   AS CHANGE_REASON
  FROM KEPMGPDT D
 WHERE D.BUYER = #{KEY_2}
   AND D.PM_NO = #{KEY_1}
 ORDER BY D.PM_SEQ

mapper.update:

/*commonMdCmBuyPriceApproval.updateBuyPriceApply*/
UPDATE CMSPRICE
   SET BUY_PRICE      = TO_NUMBER(F_HST_CMSPRICE(CMS_CATLG_ID
                                               , CATLG_SEQ
                                               , 'BUY_PRICE'
                                               , #{CH_BUY_PRICE}
                                               , #{USER_ID}
                                               , NULL
                                               , #{CHANGE_REASON}))
     , CHANGE_USER_ID = #{USER_ID}
     , CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE CMS_CATLG_ID = #{CMS_CATLG_ID}
   AND CATLG_SEQ    = TO_NUMBER(#{CATLG_SEQ})
